  <div class="spinner">Loading...</div>
  <div id="sfMount"></div>
  <!-- ADD: Choose your own ID -->
  <c-my-component></c-my-component>
  <!-- ADD -->
  <div id="lightningTarget"></div>
  <!-- KEEP if needed -->
</div>
<button id="authBtn">Login</button>
<!-- ADD id for event listener -->
